import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"26 · 设计权衡与取舍","description":"","frontmatter":{"概念":"设计权衡与取舍","技能":"system-design","阶段":"5-资深架构","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"system-design/concepts/26-design-tradeoffs.md","filePath":"system-design/concepts/26-design-tradeoffs.md","lastUpdated":null}'),e={name:"system-design/concepts/26-design-tradeoffs.md"};function l(p,s,r,h,d,o){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_26-·-设计权衡与取舍" tabindex="-1">26 · 设计权衡与取舍 <a class="header-anchor" href="#_26-·-设计权衡与取舍" aria-label="Permalink to &quot;26 · 设计权衡与取舍&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>初级工程师问「哪个方案更好」,架构师问「<strong>每个方案的代价是什么,我们付得起哪个</strong>」——这就是权衡(Tradeoff)思维。系统设计里没有「最佳实践」,只有「特定约束下的合理取舍」:强一致性还是高可用?低延迟还是低成本?架构优雅还是按时交付?本章把架构师最常面对的四组核心权衡讲透,并给出<strong>决策方法</strong>:如何系统化地比较方案、如何记录决策(ADR)让后人理解,而不是靠「我觉得」。</p><p>为什么权衡是架构师的分水岭能力?因为<strong>每个架构决策都在赌未来</strong>——选 2PC 是赌「事务量不会变大」,选微服务是赌「团队会增长」,选事件溯源是赌「审计价值 &gt; 实现复杂度」。赌输了不可怕,可怕的是不知道自己在赌、赌输了无法回退。权衡思维 = 显式列出代价 + 记录决策理由 + 预留回退路径。</p><p>对前端工程师:你每天都在做权衡——用 useState 还是全局 store(状态复杂性 vs 组件内聚)、虚拟 DOM 还是手动操作(性能 vs 可维护性)、引入 UI 组件库还是自研(速度 vs 灵活)。后端架构的权衡只是把同一套思维放到更大尺度:每个权衡的单位从「一个组件」变成「一个子系统」,从「一个版本」变成「三年演进」。学会把权衡「说出来、写下来」,是本次进阶的核心。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-权衡是架构师的主业" tabindex="-1">1. 权衡是架构师的主业 <a class="header-anchor" href="#_1-权衡是架构师的主业" aria-label="Permalink to &quot;1. 权衡是架构师的主业&quot;">​</a></h4><p>架构决策的通用框架:<strong>列出每个方案的收益、代价、风险、失效条件</strong>,再做决策:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>决策模板:</span></span>
<span class="line"><span>  问题:下单后库存一致性能否最终一致?</span></span>
<span class="line"><span>  候选 A:2PC(强一致)</span></span>
<span class="line"><span>    收益:瞬时一致,无对账成本</span></span>
<span class="line"><span>    代价:阻塞、协调者单点、事务量受限于锁</span></span>
<span class="line"><span>    风险:高并发下吞吐腰斩</span></span>
<span class="line"><span>  候选 B:可靠消息(最终一致)</span></span>
<span class="line"><span>    收益:高吞吐、无锁</span></span>
<span class="line"><span>    代价:需要补偿与对账</span></span>
<span class="line"><span>    风险:不一致窗口期内的业务误判(需产品确认)</span></span>
<span class="line"><span>  决策:选 B,不一致窗口 &lt; 5 秒,对账任务兜底</span></span></code></pre></div><p><strong>判断标准不是「哪个更先进」,而是「哪个失败的代价更小、更容易回退」</strong>。</p><h4 id="_2-一致性-vs-可用性" tabindex="-1">2. 一致性 vs 可用性 <a class="header-anchor" href="#_2-一致性-vs-可用性" aria-label="Permalink to &quot;2. 一致性 vs 可用性&quot;">​</a></h4><p>20/21 篇已经埋下伏笔,这里上升到决策层:一致性是「大家看到的是不是同一个事实」,可用性是「系统是不是一直能用」。核心场景:网络分区(必然发生)时,你牺牲哪个?</p><table tabindex="0"><thead><tr><th>场景</th><th>选 CP</th><th>选 AP</th><th>理由</th></tr></thead><tbody><tr><td>账户余额</td><td>✓</td><td></td><td>宁可不可用,不能算错账</td></tr><tr><td>商品库存</td><td></td><td>✓</td><td>宁可短暂超卖,不能拒绝下单</td></tr><tr><td>分布式锁</td><td>✓</td><td></td><td>双主执行是灾难</td></tr><tr><td>点赞数/浏览数</td><td></td><td>✓</td><td>丢了可以重算</td></tr></tbody></table><p><strong>决策要点:按数据分类做选择,而不是全系统一个策略</strong>——订单库 CP,热点统计 AP,「一致性等级」本身就是设计参数。同样重要的是把不一致窗口的<strong>业务后果</strong>量化:超卖 0.1% 的赔偿 vs 拒绝 1% 请求的流失,哪个贵选哪个。</p><h4 id="_3-延迟-vs-成本" tabindex="-1">3. 延迟 vs 成本 <a class="header-anchor" href="#_3-延迟-vs-成本" aria-label="Permalink to &quot;3. 延迟 vs 成本&quot;">​</a></h4><p>低延迟通常等于多花钱:缓存层(内存贵)、多副本(3 副本 vs 2 副本)、全球节点(边缘计算)、预留容量(闲置等待)。决策的核心是<strong>给延迟定价</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>延迟定价法:</span></span>
<span class="line"><span>  每秒 1ms 的延迟 = 收入影响?转化率下降 0.5%?</span></span>
<span class="line"><span>  → 转化率 × 客单价 × 日单量 = 延迟的年化损失</span></span>
<span class="line"><span>  → 与缓存/扩容的年成本对比,即可量化&quot;该不该加层&quot;</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例:日单 10 万,客单价 ¥100,延迟每 +1s 转化率 -1%</span></span>
<span class="line"><span>  → 年损失 ≈ 10万 × 1% × 100 × 365 ≈ ¥3,650 万</span></span>
<span class="line"><span>  → 花 ¥200 万/年把 P95 从 1s 降到 200ms,ROI 极高</span></span>
<span class="line"><span>  → 但若是内部工具(无转化概念),200ms 已足够,别多花一分</span></span></code></pre></div><p><strong>决策要点:延迟优化服务于业务指标,不是服务于架构师的自尊</strong>——「响应时间好看」不是付费理由,「转化率提升」才是。</p><h4 id="_4-简单-vs-灵活" tabindex="-1">4. 简单 vs 灵活 <a class="header-anchor" href="#_4-简单-vs-灵活" aria-label="Permalink to &quot;4. 简单 vs 灵活&quot;">​</a></h4><ul><li><strong>简单</strong>:最少组件、最直白的实现,好理解、好维护、好排障;</li><li><strong>灵活</strong>:可配置、可扩展、可插拔,能适应未来,但每个抽象都是一层复杂度与一处可能的坑。</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 反例:为了&quot;灵活&quot;给用户表预留 20 个 NULL 字段(柔性表)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user: {name, avatar, ext1, ext2, ext3, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 谁都能加,谁都不知道含义</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 正例:简单优先,需要时再演进</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user: {name, avatar}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 未来需要年龄 → 加 age 字段(数据库加列成本极低)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 未来需要多态属性 → 才考虑 EAV/JSONB</span></span></code></pre></div><p><strong>YAGNI 原则</strong>:不为「未来可能」做设计,为「今天确定」做设计——因为 90% 的「未来可能」永远不会来,而它带来的抽象复杂度是确定的。<strong>灵活性的正确来源不是预先抽象,而是演进能力</strong>(24 篇:好拆、好合、能重构)。</p><h4 id="_5-工程师时间-vs-架构优雅" tabindex="-1">5. 工程师时间 vs 架构优雅 <a class="header-anchor" href="#_5-工程师时间-vs-架构优雅" aria-label="Permalink to &quot;5. 工程师时间 vs 架构优雅&quot;">​</a></h4><p>最容易被忽略的权衡:架构师的「理想架构」消耗的是工程师的「真实时间」。优雅的代价是学习成本、实现时间、上线风险;粗糙的代价是后期重构成本。决策公式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>优化决策 = 优雅收益(未来节省) vs 实现成本(现在多花)</span></span>
<span class="line"><span>  现在的 100 人天重构,若未来 2 年能省 200 人天 → 值得</span></span>
<span class="line"><span>  现在的 50 人天,若未来省 30 人天 → 不值得,先按简单的来</span></span></code></pre></div><p><strong>关键认知:技术债不等于坏决策</strong>——明知道是权宜之计、记了账(ADR)、排了偿还计划,它就是「战略性的技术债」,是合理的工程决策;没记账的债务才是灾难(24 篇)。</p><h4 id="_6-架构决策记录-adr" tabindex="-1">6. 架构决策记录(ADR) <a class="header-anchor" href="#_6-架构决策记录-adr" aria-label="Permalink to &quot;6. 架构决策记录(ADR)&quot;">​</a></h4><p>ADR 是把权衡「写下来」的工程实践——一条决策、一份背景、几项候选、一个结论、代价与回退方案:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># ADR-007:订单库存一致性采用可靠消息方案</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">已接受(2026-08-01)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 背景</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下单需跨订单/库存/支付三个服务;高并发下 2PC 吞吐不足。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 决策</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">订单与消息同库同事务(Outbox),异步投递,消费者幂等。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 后果(代价)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 正:吞吐高、无锁、无协调者单点</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 负:不一致窗口 ≤ 5 秒;需对账任务;需培训团队理解最终一致</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 回退:若业务要求瞬时一致,可升级为 TCC(库存侧已有冻结字段)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 替代方案</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 2PC:拒绝,吞吐瓶颈 + 协调者单点(详见会议 2026-07-28)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TCC:暂缓,预留冻结字段,库存侧先上 Outbox</span></span></code></pre></div><p><strong>ADR 的三种用途</strong>:决策当时强制你想清代价;新人接手时 3 分钟理解「为什么这样」;架构评审时是「推翻它」还是「尊重它」的依据。<strong>没有 ADR 的架构决策,三个月后就是「历史遗留问题」</strong>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>用「最佳实践」替代权衡</strong>:没有「最佳」,只有「最合适」;把别人的选型当自己的答案,等于放弃思考。</li><li><strong>只列收益不列代价</strong>:答辩时只说方案 A 多好,不说它付了什么代价——评委一句话就戳穿。</li><li><strong>决策不记录</strong>:三个月后没人记得为什么选它,重构时反复推翻重来,团队为「失忆」付持续成本。</li><li><strong>过度设计(为未来做抽象)</strong>:为「可能」的多态、扩展、配置写三层抽象,业务半年不动,抽象成为负担。</li><li><strong>优化不存在的瓶颈</strong>:为 P99 的 10ms 重构架构,而真正的瓶颈是慢 SQL——先测量再优化。</li><li><strong>把回退当失败</strong>:有回退方案且能快速回退,说明决策是好的;不能回退的决策才是危险决策。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>:用「决策模板」(问题/候选/收益/代价/风险/决策)对比两个方案——如「短链系统用发号器还是哈希」,输出一份对比表。</li><li><strong>进阶</strong>:为你熟悉的一个系统写一份完整 ADR:背景、候选方案(至少 2 个)、决策、后果、回退方案,并给一个「推翻它」的论证。</li><li><strong>综合</strong>:举办一次「架构评审答辩」:准备 3 个方案(如订单一致性:2PC/TCC/Outbox),从一致性、延迟、成本、团队维护能力四个维度打分,给出最终决策与 ADR——这正是 <code>/assess system-design L5</code> 的考核形态。</li></ol><blockquote><p>用 <code>/practice system-design 设计权衡与取舍</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端</th><th>后端权衡</th></tr></thead><tbody><tr><td>useState vs 全局 store</td><td>本地状态 vs 分布式一致性</td></tr><tr><td>虚拟 DOM vs 直接操作 DOM</td><td>抽象层 vs 直给实现</td></tr><tr><td>引入 UI 组件库 vs 自研</td><td>第三方中间件 vs 自建</td></tr><tr><td>优化 bundle vs 开发速度</td><td>优雅架构 vs 工程师时间</td></tr><tr><td>预渲染/SSR vs CSR</td><td>强一致 vs 低延迟</td></tr><tr><td>前端技术债(TODO/评论)</td><td>ADR 架构决策记录</td></tr><tr><td>性能预算 vs 功能迭代</td><td>延迟成本 vs 业务收益</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://adr.github.io/" target="_blank" rel="noreferrer">ADR(Architecture Decision Records)</a></li><li><a href="https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions" target="_blank" rel="noreferrer">Michael Nygard:Documenting Architecture Decisions</a></li><li><a href="https://docs.aws.amazon.com/whitepapers/latest/architecture-framework/architecture-framework.html" target="_blank" rel="noreferrer">AWS 架构完善框架(Well-Architected,六大支柱含权衡)</a></li><li><a href="https://martinfowler.com/bliki/Yagni.html" target="_blank" rel="noreferrer">Martin Fowler:YAGNI</a></li></ul>`,40)])])}const k=a(e,[["render",l]]);export{g as __pageData,k as default};
